#!/usr/bin/env node
/**
 * Turns on R8 code shrinking and resource shrinking for the Android release
 * build.
 *
 * The `android/` project is generated by `npx cap add android` in CI and is not
 * committed, so this patch runs against the freshly generated Gradle files
 * instead of being checked in. Capacitor's template ships
 * `minifyEnabled false`, which leaves ~1.5 MB of unused Capacitor/AndroidX
 * classes and resources in the APK.
 *
 * Deliberately non-fatal: if a future Capacitor template changes these lines,
 * the build should still produce a (larger) APK rather than fail the release.
 */

import { readFileSync, writeFileSync, existsSync, appendFileSync } from 'node:fs'

const GRADLE = 'android/app/build.gradle'
const PROGUARD = 'android/app/proguard-rules.pro'

/** Keep rules for the classes Android instantiates reflectively. */
const KEEP_RULES = `
# ─── PixelDeck ───────────────────────────────────────────────────────────────
# Capacitor resolves plugins and the bridge by name at runtime, so R8 must not
# rename or drop them even though nothing references them statically.
-keep class com.getcapacitor.** { *; }
-keep @com.getcapacitor.annotation.CapacitorPlugin class * { *; }
-keep class * extends com.getcapacitor.Plugin { *; }

# WebView JS bridges are called from JavaScript, which R8 cannot see.
-keepclassmembers class * {
    @android.webkit.JavascriptInterface <methods>;
}
`

function warn(message) {
  console.warn(`[shrink-android-release] ${message}`)
}

if (!existsSync(GRADLE)) {
  warn(`${GRADLE} not found — run "npx cap add android" first. Skipping.`)
  process.exit(0)
}

let gradle = readFileSync(GRADLE, 'utf8')

if (/minifyEnabled\s+true/.test(gradle)) {
  console.log('[shrink-android-release] Shrinking already enabled — nothing to do.')
} else if (/minifyEnabled\s+false/.test(gradle)) {
  gradle = gradle.replace(
    /minifyEnabled\s+false/,
    'minifyEnabled true\n            shrinkResources true',
  )
  writeFileSync(GRADLE, gradle)
  console.log('[shrink-android-release] Enabled minifyEnabled + shrinkResources.')
} else {
  warn(
    'no "minifyEnabled false" line in the Capacitor template — the APK will ' +
      'build unshrunk. Check whether the template changed.',
  )
}

if (existsSync(PROGUARD)) {
  const rules = readFileSync(PROGUARD, 'utf8')
  if (rules.includes('PixelDeck')) {
    console.log('[shrink-android-release] Keep rules already present.')
  } else {
    appendFileSync(PROGUARD, KEEP_RULES)
    console.log('[shrink-android-release] Appended Capacitor keep rules.')
  }
} else {
  writeFileSync(PROGUARD, KEEP_RULES.trimStart())
  console.log('[shrink-android-release] Wrote Capacitor keep rules.')
}
